package org.ev6.aarelab;
import android.app.*;import android.os.*;import android.media.*;import android.view.*;import android.widget.*;
public final class MainActivity extends Activity {
 TextView status;int taps;volatile AudioTrack track;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(32,70,32,32);root.setBackgroundColor(0xff102330);TextView title=new TextView(this);title.setText("AARE Lab — display / touch / audio");title.setTextColor(-1);title.setTextSize(23);root.addView(title);status=new TextView(this);status.setText("Touch count: 0");status.setTextColor(0xff44dddd);status.setTextSize(24);root.addView(status);Button tap=new Button(this);tap.setText("TOUCH TEST");tap.setOnClickListener(new View.OnClickListener(){public void onClick(View v){taps++;status.setText("Touch count: "+taps);}});root.addView(tap,new LinearLayout.LayoutParams(-1,90));Button play=new Button(this);play.setText("PLAY 3s QUIET TEST TONE");play.setOnClickListener(new View.OnClickListener(){public void onClick(View v){tone();}});root.addView(play,new LinearLayout.LayoutParams(-1,90));Button stop=new Button(this);stop.setText("STOP SOUND");stop.setOnClickListener(new View.OnClickListener(){public void onClick(View v){stopTone();}});root.addView(stop,new LinearLayout.LayoutParams(-1,90));setContentView(root);}
 void stopTone(){AudioTrack a=track;track=null;if(a!=null)try{a.stop();a.release();}catch(Exception ignored){}}
 void tone(){stopTone();new Thread(new Runnable(){public void run(){try{int rate=48000,n=rate*3;short[] pcm=new short[n];for(int i=0;i<n;i++){double fade=Math.min(1,Math.min(i/480.0,(n-i)/480.0));pcm[i]=(short)(1800*fade*Math.sin(2*Math.PI*(i<rate*1.5?440:660)*i/rate));}final AudioTrack a=new AudioTrack(AudioManager.STREAM_MUSIC,rate,AudioFormat.CHANNEL_OUT_MONO,AudioFormat.ENCODING_PCM_16BIT,n*2,AudioTrack.MODE_STATIC);track=a;a.write(pcm,0,n);a.play();android.util.Log.i("AARELab","TONE_START 440Hz_then_660Hz PCM16 48000Hz 3s");Thread.sleep(3300);if(track==a)stopTone();android.util.Log.i("AARELab","TONE_END");}catch(Exception e){android.util.Log.e("AARELab","tone",e);}}},"LabTone").start();}
 public void onDestroy(){stopTone();super.onDestroy();}
}
